import com.adeptia.model.TransactionDetails;
import com.adeptia.service.RuntimeService;
import com.adeptia.api.rest.spring.utils.BeanFactory;
import com.adeptia.indigo.event.EventUtils;
import com.adeptia.indigo.event.mailtrigger.MessageDigest;
import com.adeptia.indigo.logging.Logger;
import java.util.HashMap;
import java.util.Map;

// Code variables
Map hashMap = new HashMap();
Map eventContextMap = new HashMap();
Logger logger = Logger.getLogger("Event", subject);

/* *************
    Write your logic here
************* */

// Setting up values in the context variables
eventContextMap.put("contextVariableName","contextVariableValue");
// Example:
eventContextMap.put("PolicyNumber", "0658932");

// Optional overrides - uncomment only the one matching your source activity
// (source activity must use eventContextEnable=true)

// File source
// String fileToOverride = "<Enter the file location along with file name to override>";
// hashMap.put(EventUtils.FILEPATH, fileToOverride);

// Database source
// String whereClauseQuery = "<Enter the database WHERE CLAUSE to override.>";
// hashMap.put("QUERY", whereClauseQuery);

// Using event context map to pass event variables
eventContextMap.put(EventUtils.EVENTCONTEXTVAR, hashMap);

// Queue Processor parameters
String eventId = "1555162352799178752";
eventId = "ComplexEvent:" + eventId;
hashMap.put("EventID", eventId);

String eventName = "SG_Complex_Event_RunOnce";
hashMap.put("EventName", eventName);

// Define process flow
String processFlowId = "1555107801211940864";

// Add information to event log
logger.info("Executing Process Flow - SG_PF_Text_2_Text_Container_Shipments, using the Complex Event");

// Trigger the process flow
eventContextMap.put("EventID", eventId);
eventContextMap.put("EventType", "ComplexEvent");
RuntimeService runtimeService = BeanFactory.getBean(RuntimeService.class);
TransactionDetails txn = TransactionDetails.builder()
        .transactionId(processFlowId).context(eventContextMap).subject(subject).build();
runtimeService.submitJobForProcessing(txn, logger);
